def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 == 0:
        return None

    change = v2 - v1
    percentage_change = (change / v1) * 100

    return {
        "value": percentage_change,
        "trace": {
            "initial_value": v1,
            "final_value": v2,
            "change": change,
            "percentage_change": percentage_change,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
